UPDATE demo_product_stock
SET stock = stock - #{qty},
    withhold_stock = withhold_stock + #{qty},
    updated_at = NOW(3)
WHERE product_id = #{productId}
  AND stock >= #{qty}

UPDATE demo_product_stock
SET stock = stock + #{qty},
    withhold_stock = withhold_stock - #{qty},
    updated_at = NOW(3)
WHERE product_id = #{productId}
  AND withhold_stock >= #{qty}
